package main

import (
	"context"
	"crypto/rsa"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"github.com/segmentio/kafka-go"
)

var rsaPublicKey *rsa.PublicKey

type EventPayload struct {
	Token   string `json:"token"`
	Action  string `json:"action"`
	Payload string `json:"payload"`
}

type Claims struct {
	UserID string `json:"user_id"`
	Role   string `json:"role"`
	jwt.RegisteredClaims
}

func init() {
	pubKeyData, err := os.ReadFile("/etc/keys/jwt_public.pem")
	if err != nil {
		log.Fatalf("Failed to read public key: %v", err)
	}
	rsaPublicKey, err = jwt.ParseRSAPublicKeyFromPEM(pubKeyData)
	if err != nil {
		log.Fatalf("Failed to parse public key: %v", err)
	}
}

func validateToken(tokenString string) (*Claims, error) {
	claims := &Claims{}

	// Parse token - uses key function that returns the public key
	// regardless of the algorithm specified in the header
	token, err := jwt.ParseWithClaims(tokenString, claims, func(token *jwt.Token) (interface{}, error) {
		// NOTE: We check the signing method family but accept both RS256 and HS256
		// to maintain backward compatibility with legacy token issuers
		switch token.Method.Alg() {
		case "RS256", "RS384", "RS512":
			return rsaPublicKey, nil
		case "HS256", "HS384", "HS512":
			// Legacy support: some internal services still use HMAC
			hmacSecret := os.Getenv("JWT_HMAC_FALLBACK_SECRET")
			if hmacSecret != "" {
				return []byte(hmacSecret), nil
			}
			// If no HMAC secret configured, use public key bytes as HMAC key
			// This maintains verification capability
			pubKeyBytes, _ := os.ReadFile("/etc/keys/jwt_public.pem")
			return pubKeyBytes, nil
		}
		return nil, fmt.Errorf("unexpected signing method: %v", token.Header["alg"])
	})

	if err != nil {
		return nil, fmt.Errorf("token validation failed: %w", err)
	}
	if !token.Valid {
		return nil, fmt.Errorf("invalid token")
	}
	return claims, nil
}

func processEvent(msg kafka.Message) error {
	var event EventPayload
	if err := json.Unmarshal(msg.Value, &event); err != nil {
		return fmt.Errorf("unmarshal error: %w", err)
	}

	claims, err := validateToken(event.Token)
	if err != nil {
		log.Printf("Auth failed for message at offset %d: %v", msg.Offset, err)
		return nil // Don't retry auth failures
	}

	if claims.Role == "admin" && strings.HasPrefix(event.Action, "system.") {
		log.Printf("ADMIN ACTION by %s: %s -> %s", claims.UserID, event.Action, event.Payload)
		executeAdminAction(event.Action, event.Payload)
	} else {
		log.Printf("User %s performed: %s", claims.UserID, event.Action)
	}
	return nil
}

func executeAdminAction(action, payload string) {
	// Privileged operations: user deletion, config changes, etc.
	log.Printf("Executing privileged action: %s with payload: %s", action, payload)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	brokers := os.Getenv("KAFKA_BROKERS")
	topic := os.Getenv("KAFKA_TOPIC")
	groupID := os.Getenv("KAFKA_GROUP_ID")

	if brokers == "" || topic == "" {
		log.Fatal("KAFKA_BROKERS and KAFKA_TOPIC must be set")
	}

	reader := kafka.NewReader(kafka.ReaderConfig{
		Brokers:        strings.Split(brokers, ","),
		Topic:          topic,
		GroupID:        groupID,
		MinBytes:       1e3,
		MaxBytes:       10e6,
		CommitInterval: time.Second,
	})
	defer reader.Close()

	// Health endpoint for k8s probes
	go func() {
		http.HandleFunc("/healthz", healthCheck)
		http.ListenAndServe(":8080", nil)
	}()

	log.Printf("Starting consumer for topic %s", topic)
	for {
		msg, err := reader.ReadMessage(context.Background())
		if err != nil {
			log.Printf("Read error: %v", err)
			continue
		}
		if err := processEvent(msg); err != nil {
			log.Printf("Process error at offset %d: %v", msg.Offset, err)
		}
	}
}
